const safeHref=value=>{try{const url=new URL(value,location.origin);return(url.protocol==='https:'||url.origin===location.origin)&&!url.username&&!url.password?url.href:null;}catch{return null;}};
function appendInline(parent,value){const pattern=/\[([^\]]+)\]\((https?:\/\/[^\s)]+|\/[^\s)]*)\)|(\*\*[^*]+\*\*|\*[^*]+\*)/g;let start=0,match;while((match=pattern.exec(value))){parent.append(document.createTextNode(value.slice(start,match.index)));if(match[1]){const href=safeHref(match[2]);if(href){const link=document.createElement('a');link.href=href;link.rel='noopener noreferrer';link.textContent=match[1];parent.append(link);}else parent.append(document.createTextNode(match[1]));}else if(match[3].startsWith('**')){const strong=document.createElement('strong');strong.textContent=match[3].slice(2,-2);parent.append(strong);}else{const emphasis=document.createElement('em');emphasis.textContent=match[3].slice(1,-1);parent.append(emphasis);}start=pattern.lastIndex;}parent.append(document.createTextNode(value.slice(start)));}
export function renderRichText(target,value){if(!target)return;target.replaceChildren();const lines=String(value||'').split(/\r?\n/);let list=null;for(const raw of lines){const line=raw.trim();if(!line){list=null;continue;}if(line.startsWith('- ')){if(!list){list=document.createElement('ul');target.append(list);}const item=document.createElement('li');appendInline(item,line.slice(2));list.append(item);continue;}list=null;const heading=line.match(/^(#{1,3})\s+(.+)$/),element=document.createElement(heading?'h'+heading[1].length:'p');appendInline(element,heading?heading[2]:line);target.append(element);}}
export function insertRichTextMarker(textarea,before,after=''){const start=textarea.selectionStart,end=textarea.selectionEnd,selected=textarea.value.slice(start,end);textarea.setRangeText(before+selected+after,start,end,'select');textarea.dispatchEvent(new Event('input',{bubbles:true}));textarea.focus();}
